INSERT INTO pricing_catalogues (id, catalogue, published, updated_at) VALUES ('default', '{"plans": [{"id": "tier_free", "tier": "free", "name": "Free", "subtitle": "Essential starter workspace with 3 notes, community view access, and core trading tools", "monthly_amount": 0.0, "annual_monthly_amount": 0.0, "currency_symbol": "₹", "features_summary": ["Up to 3 research notes", "Community feed & public post view access", "Up to 15 logged trades (total)", "1 active playbook & 1 watchlist", "Up to 5 AI prompts per month", "Core calculators & market view"], "badge_label": "AVAILABLE NOW", "highlighted": false, "is_current": false, "cta_label": "Continue with Free", "limits": {"notes": 3, "trades": 15, "live_playbooks": 1, "watchlists": 1, "ai_queries_per_month": 5}, "is_purchasable": true}, {"id": "tier_pro", "tier": "premium", "name": "Basic", "subtitle": "Expanded trading workspace; monthly subscriptions are disabled for now", "monthly_amount": 299.0, "annual_monthly_amount": 239.0, "currency_symbol": "₹", "features_summary": ["Up to 25 research notes", "Up to 100 logged trades (total)", "Up to 3 active playbooks", "Up to 20 AI prompts per month", "Full community participation & market data", "Monthly subscriptions disabled for now"], "badge_label": "MONTHLY SUBSCRIPTIONS DISABLED", "highlighted": true, "is_current": false, "cta_label": "Monthly subscriptions disabled", "limits": {"notes": 25, "trades": 100, "live_playbooks": 3, "watchlists": 1, "ai_queries_per_month": 20}, "is_purchasable": false}, {"id": "tier_enterprise", "tier": "enterprise", "name": "Pro", "subtitle": "High-capacity professional workspace; monthly subscriptions are disabled for now", "monthly_amount": 499.0, "annual_monthly_amount": 399.0, "currency_symbol": "₹", "features_summary": ["Up to 10,000 research notes", "Up to 50,000 logged trades (total)", "Up to 250 active playbooks & 100 watchlists", "Up to 5,000 AI prompts per month", "PDF & CSV exports + advanced analytics", "Monthly subscriptions disabled for now"], "badge_label": "MONTHLY SUBSCRIPTIONS DISABLED", "highlighted": false, "is_current": false, "cta_label": "Monthly subscriptions disabled", "limits": {"notes": 10000, "trades": 50000, "live_playbooks": 250, "watchlists": 100, "ai_queries_per_month": 5000}, "is_purchasable": false}], "categories": [{"id": "cat_limits", "name": "Enforced workspace limits", "rows": [{"id": "feat_notes", "title": "Research notes", "tooltip": "Maximum saved research notes. New-note actions check this limit.", "free_value": "3 total", "pro_value": "25 total", "enterprise_value": "10,000 total", "is_boolean": false}, {"id": "feat_trades", "title": "Logged trades", "tooltip": "Maximum saved journal trades. New-trade actions check this limit.", "free_value": "15 total", "pro_value": "100 total", "enterprise_value": "50,000 total", "is_boolean": false}, {"id": "feat_playbooks", "title": "Active playbooks", "tooltip": "Maximum active strategy playbooks. Creation actions check this limit.", "free_value": "1 active", "pro_value": "3 active", "enterprise_value": "250 active", "is_boolean": false}, {"id": "feat_ai", "title": "AI prompts", "tooltip": "Monthly server-side quota for AI requests.", "free_value": "5 / month", "pro_value": "20 / month", "enterprise_value": "5,000 / month", "is_boolean": false}]}, {"id": "cat_access", "name": "Current availability", "rows": [{"id": "feat_charts", "title": "Charts and market browsing", "tooltip": "Available data depends on the configured provider and its coverage; real-time depth is not guaranteed.", "free_value": "View access", "pro_value": "Full access", "enterprise_value": "Full access", "is_boolean": false}, {"id": "feat_community", "title": "Community access", "tooltip": "Free includes community view access; Basic and Pro include full community participation.", "free_value": "View access", "pro_value": "Full access", "enterprise_value": "Full access", "is_boolean": false}, {"id": "feat_checkout", "title": "Monthly subscriptions", "tooltip": "Monthly subscriptions for Basic and Pro are temporarily disabled.", "free_value": "Not needed", "pro_value": "Disabled for now", "enterprise_value": "Disabled for now", "is_boolean": false}]}], "faqs": [{"id": "faq_billing", "category": "billing", "question": "Can I subscribe to Basic or Pro monthly right now?", "answer": "Monthly subscriptions for Basic and Pro are disabled for now. You can use the Free plan (up to 3 notes, 15 trades, 1 playbook, and community view access) immediately."}, {"id": "faq_limits", "category": "features", "question": "Which limits are checked today?", "answer": "The app checks total saved notes (3 on Free, 25 on Basic, 10,000 on Pro), total logged trades (15 on Free, 100 on Basic, 50,000 on Pro), active playbooks (1 on Free, 3 on Basic, 250 on Pro), and monthly server-side AI prompt quotas (5 on Free, 20 on Basic, 5,000 on Pro)."}, {"id": "faq_data", "category": "features", "question": "Is market data real-time?", "answer": "Coverage and delay depend on the connected data provider. alphajournal does not currently promise tick-by-tick depth or exchange-grade low latency."}, {"id": "faq_tax", "category": "billing", "question": "Are paid prices final, including taxes?", "answer": "Basic (₹299/mo) and Pro (₹499/mo) prices are preview rates while monthly subscriptions remain disabled."}], "annual_discount_percent": 20, "annual_months_billed": 12, "footer_disclaimer": "Free includes up to 3 notes and community view access. Monthly subscriptions for Basic and Pro are disabled for now.", "copy": {"badge": "Plans for every workspace", "title": "Choose Your Trading Plan", "description": "Start on Free with 3 notes and community view access. Monthly subscriptions for Basic and Pro are disabled for now.", "monthly": "Monthly", "annual": "Billed annually", "current": "Current Plan", "processing": "Processing…", "matrix": "Compare Features Across Plans", "faq": "Frequently Asked Questions", "all": "All Questions", "retry": "Try again", "back": "Back", "error": "Unable to load pricing", "billing_suffix": "/month", "annual_savings": "Monthly subscriptions are currently disabled for Basic and Pro", "feature": "Feature"}}'::jsonb, true, now()) ON CONFLICT (id) DO UPDATE SET catalogue = EXCLUDED.catalogue, published = true, updated_at = now();
INSERT INTO public_site_pages (id, content, published) VALUES ('landing', '{"brand": "alphajournal", "title": "The Foundation for your Trading System", "description": "AI analysis, quantitative journaling, market intelligence, and community in one workspace. Built for precision, clarity, and disciplined execution.", "signin_label": "Sign in", "start_label": "Get Started Free", "pricing_label": "Explore Plans", "features_title": "Tools for Every Trading Decision", "roles_title": "Choose Your Workspace", "pricing_title": "Plans for Your Trading Workspace", "faq_title": "Frequently Asked Questions", "footer": "alphajournal · A workspace for disciplined traders. Market information is provided for research; it is not investment advice.", "retry_label": "Try again", "error_title": "Unable to load page content", "features": [{"title": "Institutional Community", "description": "Share setups, discuss markets, and follow traders across a curated community.", "icon": "forum"}, {"title": "Quantitative Journaling", "description": "Record execution, review equity curves, and connect notes with your trading playbooks.", "icon": "book"}, {"title": "Market Intelligence", "description": "Browse market news, instrument snapshots, price history, and company fundamentals.", "icon": "news"}, {"title": "AI Trading Assistant", "description": "Review charts and trading ideas with context from your workspace.", "icon": "ai"}], "roles": [{"id": "customer", "title": "Trader", "description": "Build discipline with journals, strategies, notes, and a trading community.", "cta": "Get Started as Trader"}, {"id": "affiliate", "title": "Affiliate", "description": "Grow your audience with referral links, campaign tracking, and transparent commissions.", "cta": "Apply as Affiliate"}], "faqs": [{"id": "landing_records", "category": "features", "question": "How do notes, journals, and strategies connect?", "answer": "Link your private writing records and selectively publish individual records to the community."}, {"id": "landing_roles", "category": "general", "question": "Who can join alphajournal?", "answer": "Traders can create a trading workspace. Affiliates can apply for a partner workspace."}]}'::jsonb, true) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, published = EXCLUDED.published;
COMMIT;
